640:     if (state.phase !== 'ready' || runId !== null) return
641:     const typing = isTyping(event.target)
642:     const mod = event.ctrlKey || event.metaKey
643:     const key = event.key.toLowerCase()
644:     if (key === 'escape') {
645:       if (typing) return
646:       if (quick !== null) setQuick(null)
647:       else select(null)
