649:     }
650:     if (typing) return
651:     if (mod && (key === 'z' || key === 'y')) {
652:       event.preventDefault()
653:       if (key === 'y' || event.shiftKey) wf.redo()
654:       else wf.undo()
655:       return
656:     }
657:     if (mod && key === 'd') {
658:       event.preventDefault()
659:       if (state.selection?.kind === 'node') duplicate(state.selection.id)
660:       return
661:     }
662:     // 其余修饰键组合留给宿主（浏览器查找之类）。
663:     if (mod || event.altKey) return
